const event = items[0].json;
const object = (event.data && event.data.object) || {};
const type = event.type || 'unknown';
const currency = String(object.currency || '').toLowerCase();
const zeroDecimal = new Set([
  'bif', 'clp', 'djf', 'gnf', 'jpy', 'kmf', 'krw', 'mga',
  'pyg', 'rwf', 'ugx', 'vnd', 'vuv', 'xaf', 'xof', 'xpf',
]);

let rawAmount = 0;
let reason = '';
let url = '';
if (type === 'invoice.payment_failed') {
  rawAmount = Number(object.amount_due || 0);
  reason = object.billing_reason || 'invoice payment failed';
  url = object.hosted_invoice_url || '';
} else {
  rawAmount = Number(object.amount || 0);
  reason = object.failure_message || object.failure_code || 'charge failed';
  url = object.receipt_url || '';
}

const amount = zeroDecimal.has(currency) ? rawAmount : rawAmount / 100;
const customer = object.customer_email
  || object.receipt_email
  || (object.billing_details && object.billing_details.email)
  || object.customer
  || 'unknown';

const lines = [
  '*Payment failed* (' + type + ')',
  'Customer: ' + customer,
  'Amount: ' + amount + ' ' + currency.toUpperCase(),
  'Reason: ' + reason,
];
if (url) lines.push(url);
if (event.id) lines.push('Event: ' + event.id);

return [{
  json: {
    text: lines.join('\n'),
    type,
    customer,
    amount,
    currency,
    reason,
    url,
    eventId: event.id || '',
  },
}];
